mapper.select:
SELECT id, event_id, case_id, camera_id, source_type, analysis_job_id, recording_id,
       detected_at, frame_object_key, created_at
FROM candidate_events WHERE event_id = #{eventId}

SELECT EXISTS (
    SELECT 1 FROM case_cameras
    WHERE case_id = #{caseId} AND camera_id = #{cameraId}
      AND search_enabled = TRUE AND removed_at IS NULL
)
